#pragma scop
const int TILE_I = 64;

#pragma omp parallel for
for (int i = 0; i < _PB_N; i++)
    y[i] = SCALAR_VAL(0.0);

#pragma omp parallel
{
    DATA_TYPE *y_private = (DATA_TYPE*)calloc(_PB_N, sizeof(DATA_TYPE));
    if (y_private == NULL) exit(1);

    #pragma omp for nowait
    for (int ii = 0; ii < _PB_M; ii += TILE_I) {
        int i_end = (ii + TILE_I) > _PB_M ? _PB_M : (ii + TILE_I);

        for (int i = ii; i < i_end; i++) {
            DATA_TYPE temp = SCALAR_VAL(0.0);
            #pragma omp simd reduction(+:temp)
            for (int j = 0; j < _PB_N; j++) {
                temp += A[i][j] * x[j];
            }
            tmp[i] = temp;
        }

        for (int i = ii; i < i_end; i++) {
            #pragma omp simd
            for (int j = 0; j < _PB_N; j++) {
                y_private[j] += A[i][j] * tmp[i];
            }
        }
    }

    #pragma omp critical
    {
        #pragma omp simd
        for (int j = 0; j < _PB_N; j++) {
            y[j] += y_private[j];
        }
    }
    free(y_private);
}
#pragma endscop
```

